 p_id=>wwv_flow_imp.id(7959084837301833)
,p_plug_name=>'Transfer Trail'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>2674017834225413037
,p_plug_display_sequence=>10
,p_plug_display_point=>'REGION_POSITION_01'
,p_location=>null
,p_plug_query_num_rows=>15
,p_region_image=>'#APP_FILES#icons/app-icon-512.png'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML',
  'show_line_breaks', 'Y')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7964072128299526)
,p_plug_name=>'Catalog Requirements'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>4072358936313175081
,p_plug_display_sequence=>40
,p_location=>null
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_html CLOB := '''';',
'BEGIN',
'    IF :P1_PROGRAM_ID IS NOT NULL THEN',
'        -- === GE Requirements Section ===',
'        v_html := v_html || ''<h2 style="margin: 32px 0 16px 0; font-size: 1.5em;">General Education Requirements</h2>'';',
'        v_html := v_html || ''<table style="width: 100%; border-collapse: collapse; margin-bottom: 32px; font-family: system-ui, sans-serif; font-size: 14px;">'';',
'        v_html := v_html || ''<thead><tr style="border-bottom: 2px solid #ccc;">'' ||',
'                           ''<th style="width: 30px;"></th>'' ||',
'                           ''<th style="text-align: left; padding: 4px 8px;">GE Area</th>'' ||',
'                           ''<th style="text-align: left; padding: 4px 8px;">Requirement Name</th>'' ||',
'                           ''<th style="text-align: left; padding: 4px 8px;">Status</th>'' ||',
'                           ''</tr></thead><tbody>'';',
'',
'        FOR ge IN (',
'            SELECT gr.ID,',
'                   gr.GE_CODE,',
'                   gr.NAME,',
'                   CASE',
'                       WHEN EXISTS (',
'                           SELECT 1 ',
'                           FROM GE_EXCEPTIONS e ',
'                           WHERE e.PROGRAM_ID = :P1_PROGRAM_ID ',
'                             AND e.GE_REQUIREMENT_ID = gr.ID ',
'                             AND e.EXCEPTION_TYPE = ''Waived''',
'                       ) THEN ''Waived''',
'                       WHEN EXISTS (',
'                           SELECT 1 ',
'                           FROM GE_EXCEPTIONS e ',
'                           WHERE e.PROGRAM_ID = :P1_PROGRAM_ID ',
'                             AND e.GE_REQUIREMENT_ID = gr.ID ',
'                             AND e.EXCEPTION_TYPE = ''Substitution''',
'                       ) THEN ',
'                           ''Substituted by '' || (',
'                               SELECT LISTAGG(c.SUBJECT || '' '' || c.CATALOG_NUMBER, '', '') ',
'                               FROM GE_EXCEPTIONS e',
'                               JOIN COURSES c ON c.COURSE_ID = e.FULFILLED_BY_COURSE',
'                               WHERE e.PROGRAM_ID = :P1_PROGRAM_ID ',
'                                 AND e.GE_REQUIREMENT_ID = gr.ID ',
'                                 AND e.EXCEPTION_TYPE = ''Substitution''',
'                           )',
'                       ELSE ''Required''',
'                   END AS GE_STATUS,',
'                   (SELECT COUNT(*)',
'                    FROM GE_COMPLETED gc',
'                    WHERE gc.USER_ID = :APP_USER',
'                      AND gc.GE_REQUIREMENT_ID = gr.ID) AS IS_DONE',
'            FROM GE_REQUIREMENTS gr',
'            ORDER BY gr.GE_CODE',
'        )',
'        LOOP',
'            v_html := v_html || ''<tr style="border-bottom: 1px solid #eee;">'';',
'',
'            v_html := v_html || ''<td style="text-align: center;">'' ||',
'                                ''<input type="checkbox" class="ge-checkbox" value="'' || ge.ID || ''" data-ge="'' || ge.GE_CODE || ''"'';',
'            IF ge.IS_DONE > 0 THEN',
'                v_html := v_html || '' checked'';',
'            END IF;',
'            v_html := v_html || ''></td>'';',
'',
'            v_html := v_html || ''<td style="padding: 4px 8px;"><strong>'' || ge.GE_CODE || ''</strong></td>'';',
'            v_html := v_html || ''<td style="padding: 4px 8px;">'' || ge.NAME || ''</td>'';',
'            v_html := v_html || ''<td style="padding: 4px 8px;">'' || ge.GE_STATUS || ''</td>'';',
'',
'            v_html := v_html || ''</tr>'';',
'        END LOOP;',
'',
'        v_html := v_html || ''</tbody></table>'';',
'',
'        -- === Program Requirements Section ===',
'        FOR grp IN (',
'            SELECT prg.GROUP_ID,',
'                   prg.NAME AS REQUIREMENT_GROUP_NAME,',
'                   prg.DISPLAY_ORDER',
'            FROM PROGRAM_REQUIREMENT_GROUPS prg',
'            WHERE prg.PROGRAM_ID = :P1_PROGRAM_ID',
'              AND prg.DISPLAY_ORDER IS NOT NULL',
'            ORDER BY prg.DISPLAY_ORDER, prg.NAME',
'        )',
'        LOOP',
'            v_html := v_html || ''<h2 style="margin: 32px 0 16px 0; font-size: 1.5em;">'' || grp.REQUIREMENT_GROUP_NAME || ''</h2>'';',
'            v_html := v_html || ''<table style="width: 100%; border-collapse: collapse; margin-bottom: 32px; font-family: system-ui, sans-serif; font-size: 14px;">'';',
'            v_html := v_html || ''<thead><tr style="border-bottom: 2px solid #ccc;">'' ||',
'                               ''<th style="width: 30px;"></th>'' ||',
'                               ''<th style="text-align: left; padding: 4px 8px;">Course</th>'' ||',
'                               ''<th style="text-align: left; padding: 4px 8px;">Title</th>'' ||',
'                               ''<th style="text-align: left; padding: 4px 8px;">Units</th>'' ||',
'                               ''</tr></thead><tbody>'';',
'',
'            -- Courses (only in lowest DISPLAY_ORDER group)',
'            FOR crs IN (',
'                SELECT ',
'                    MIN(pcwd.COURSE_ID) AS COURSE_ID,',
'                    pcwd.CATALOG_NUMBER,',
'                    pcwd.COURSE_TITLE,',
'                    pcwd.MIN_UNITS,',
'                    pcwd.MAX_UNITS,',
'                    LISTAGG(pcwd.SUBJECT, ''/'') WITHIN GROUP (ORDER BY pcwd.SUBJECT) AS COMBINED_SUBJECT,',
'                    (',
'                        SELECT COUNT(*) ',
'                        FROM COURSES_COMPLETED cc',
'                        WHERE cc.COURSE_ID IN (',
'                            SELECT COURSE_ID',
'                            FROM PROGRAM_COURSES_WITH_DETAILS pcwd2',
'                            WHERE pcwd2.PROGRAM_ID = :P1_PROGRAM_ID',
'                              AND pcwd2.GROUP_ID = grp.GROUP_ID',
'                              AND pcwd2.CATALOG_NUMBER = pcwd.CATALOG_NUMBER',
'                        )',
'                        AND cc.USER_ID = :APP_USER',
'                    ) AS IS_DONE',
'                FROM PROGRAM_COURSES_WITH_DETAILS pcwd',
'                JOIN PROGRAM_REQUIREMENT_GROUPS prg ON pcwd.GROUP_ID = prg.GROUP_ID',
'                WHERE pcwd.PROGRAM_ID = :P1_PROGRAM_ID',
'                  AND pcwd.GROUP_ID = grp.GROUP_ID',
'                  AND pcwd.CATALOG_NUMBER IS NOT NULL',
'                  AND prg.DISPLAY_ORDER = (',
'                      SELECT MIN(prg2.DISPLAY_ORDER)',
'                      FROM PROGRAM_COURSES_WITH_DETAILS pcwd2',
'                      JOIN PROGRAM_REQUIREMENT_GROUPS prg2 ON pcwd2.GROUP_ID = prg2.GROUP_ID',
'                      WHERE pcwd2.PROGRAM_ID = :P1_PROGRAM_ID',
'                        AND pcwd2.CATALOG_NUMBER = pcwd.CATALOG_NUMBER',
'                        AND prg2.DISPLAY_ORDER IS NOT NULL',
'                  )',
'                GROUP BY ',
'                    pcwd.CATALOG_NUMBER,',
'                    pcwd.COURSE_TITLE,',
'                    pcwd.MIN_UNITS,',
'                    pcwd.MAX_UNITS',
'                ORDER BY ',
'                    CASE ',
'                        WHEN REGEXP_LIKE(pcwd.CATALOG_NUMBER, ''^\d+$'') THEN TO_NUMBER(pcwd.CATALOG_NUMBER)',
'                        ELSE NULL',
'                    END,',
'                    pcwd.CATALOG_NUMBER',
'            )',
'            LOOP',
'                v_html := v_html || ''<tr style="border-bottom: 1px solid #eee;">'';',
'',
'                v_html := v_html || ''<td style="text-align: center;">'' ||',
'                                   ''<input type="checkbox" class="course-checkbox" name="completed" value="'' || crs.COURSE_ID || ''" data-course="'' || crs.CATALOG_NUMBER || ''"'';',
'                IF crs.IS_DONE > 0 THEN',
'                    v_html := v_html || '' checked'';',
'                END IF;',
'                v_html := v_html || ''></td>'';',
'',
'                v_html := v_html || ''<td style="padding: 4px 8px;"><strong>'' || crs.COMBINED_SUBJECT || '' '' || crs.CATALOG_NUMBER || ''</strong></td>'';',
'                v_html := v_html || ''<td style="padding: 4px 8px;">'' || crs.COURSE_TITLE || ''</td>'';',
'                v_html := v_html || ''<td style="padding: 4px 8px;">'';',
'                IF crs.MIN_UNITS = crs.MAX_UNITS THEN',
'                    v_html := v_html || TO_CHAR(crs.MIN_UNITS);',
'                ELSE',
unistr('                    v_html := v_html || TO_CHAR(crs.MIN_UNITS) || ''\2013'' || TO_CHAR(crs.MAX_UNITS);'),
'                END IF;',
'                v_html := v_html || ''</td></tr>'';',
'            END LOOP;',
'',
'            -- Custom notes (always included)',
'            FOR note_row IN (',
'                SELECT DISTINCT CUSTOM_TEXT',
'                FROM PROGRAM_COURSES_WITH_DETAILS',
'                WHERE PROGRAM_ID = :P1_PROGRAM_ID',
'                  AND GROUP_ID = grp.GROUP_ID',
'                  AND CUSTOM_TEXT IS NOT NULL',
'            )',
'            LOOP',
'                v_html := v_html || ''<tr><td></td><td colspan="3" style="padding: 6px 8px; font-style: italic; color: #444;">'' || note_row.CUSTOM_TEXT || ''</td></tr>'';',
'            END LOOP;',
'',
'            v_html := v_html || ''</tbody></table>'';',
'        END LOOP;',
'',
'    ELSE',
'        v_html := v_html || ''<p style="font-size: 1.1em; color: #777; margin-top: 24px;">Please select a program to view General Education and Program Requirements.</p>'';',
'    END IF;',
'',
'    RETURN v_html;',
'END;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
);
