'BEGIN',
'    IF :P1_IS_CHECKED = ''Y'' THEN',
'        BEGIN',
'            INSERT INTO COURSES_COMPLETED (USER_ID, COURSE_ID)',
'            SELECT :APP_USER, TO_NUMBER(:P1_SELECTED_COURSE_ID)',
'            FROM DUAL',
'            WHERE NOT EXISTS (',
'                SELECT 1 FROM COURSES_COMPLETED',
'                WHERE USER_ID = :APP_USER',
'                  AND COURSE_ID = TO_NUMBER(:P1_SELECTED_COURSE_ID)',
'            );',
'        EXCEPTION',
'            WHEN OTHERS THEN NULL;',
'        END;',
'    ELSIF :P1_IS_CHECKED = ''N'' THEN',
'        DELETE FROM COURSES_COMPLETED',
'        WHERE USER_ID = :APP_USER',
'          AND COURSE_ID = TO_NUMBER(:P1_SELECTED_COURSE_ID);',
'    END IF;',
'END;',
''))
,p_attribute_02=>'P1_IS_CHECKED,P1_SELECTED_COURSE_ID'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
end;
