wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(9756666848520421)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Insert Completed Course'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_institution_id INSTITUTIONS.INSTITUTION_ID%TYPE;',
'    v_course_id COURSES.COURSE_ID%TYPE;',
'    v_exists NUMBER;',
'BEGIN',
'    -- Get institution ID',
'    SELECT institution_id',
'    INTO v_institution_id',
'    FROM institutions',
'    WHERE UPPER(name) = UPPER(:P2_INSTITUTION_NAME);',
'',
'    -- Get course ID',
'    SELECT course_id',
'    INTO v_course_id',
'    FROM courses',
'    WHERE UPPER(subject) = UPPER(:P2_SUBJECT)',
'      AND UPPER(catalog_number) = UPPER(:P2_COURSE_NUMBER)',
'      AND institution_id = v_institution_id;',
'',
'    -- Check for duplicates',
'    SELECT COUNT(*)',
'    INTO v_exists',
'    FROM courses_completed',
'    WHERE user_id = :APP_USER',
'      AND course_id = v_course_id;',
'',
'    IF v_exists = 0 THEN',
'        INSERT INTO courses_completed (user_id, course_id)',
'        VALUES (:APP_USER, v_course_id);',
'    END IF;',
'',
'    -- Clear form',
'    :P2_SUBJECT := NULL;',
'    :P2_COURSE_NUMBER := NULL;',
'    :P2_INSTITUTION_NAME := NULL;',
'',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        APEX_ERROR.ADD_ERROR (',
'            p_message => ''Course or institution not found.'',',
'            p_display_location => apex_error.c_inline_in_notification',
'        );',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(9756388511520418)
,p_internal_uid=>9756666848520421
);
end;
/
