,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    p.name AS program_name,',
'    ',
'    -- To Institution',
'    i1.name AS to_institution,',
'    c1.subject || '' '' || c1.catalog_number AS to_course_code,',
'    c1.title AS to_course_title,',
'    c1.min_units AS to_units,',
'',
'    -- From Institution',
'    i2.name AS from_institution,',
'    c2.subject || '' '' || c2.catalog_number AS from_course_code,',
'    c2.title AS from_course_title,',
'    c2.min_units AS from_units,',
'',
'    ca.notes',
'',
'FROM program_requirements pr',
'JOIN programs p ON pr.program_id = p.program_id',
'JOIN courses c1 ON pr.course_id = c1.course_id',
'JOIN course_articulations ca ON ca.course_id_1 = c1.course_id',
'JOIN courses c2 ON ca.course_id_2 = c2.course_id',
'JOIN institutions i1 ON c1.institution_id = i1.institution_id',
'JOIN institutions i2 ON c2.institution_id = i2.institution_id',
'',
'WHERE pr.program_id = :P1_PROGRAM_ID',
'ORDER BY c1.subject, c1.catalog_number;',
''))
