wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(9754629605520401)
,p_plug_name=>'Pathway'
,p_title=>' Pathway: &P5_PROGRAM_NAME.'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>4072358936313175081
,p_plug_display_sequence=>10
,p_location=>null
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_html CLOB := '''';',
'    v_row_num NUMBER;',
'    v_total_units NUMBER;',
'    v_total_max_units NUMBER;',
'BEGIN',
'    FOR sem IN (',
'        SELECT DISTINCT SEMESTER_NUMBER',
'        FROM RECOMMENDED_PATHWAY',
'        WHERE PROGRAM_ID = :P1_PROGRAM_ID',
'        ORDER BY SEMESTER_NUMBER',
'    ) ',
'    LOOP',
'        v_total_units := 0;',
'        v_total_max_units := 0;',
'',
'        v_html := v_html || ''',
'        <h2 style="margin-top: 32px; font-size: 1.5em; color: #2c3e50;">Semester '' || sem.SEMESTER_NUMBER || ''</h2>',
'        <div style="overflow-x: auto;">',
'        <table class="sortable-semester" data-semester="'' || sem.SEMESTER_NUMBER || ''" style="',
'            width: 100%; ',
'            border-collapse: collapse; ',
'            margin-bottom: 32px; ',
'            font-family: system-ui, sans-serif; font-size: 14px;',
'            box-shadow: 0 2px 8px rgba(0, 0, 0, 0.05); ',
'        ">',
'            <thead style="background-color: #f4f6f8;">',
'                <tr>',
'                    <th></th>',
'                    <th style="text-align: left; padding: 12px 16px;">Item</th>',
'                    <th style="text-align: left; padding: 12px 16px;">Details</th>',
'                    <th style="text-align: left; padding: 12px 16px;">Units</th>',
'                </tr>',
'            </thead>',
'            <tbody>'';',
'',
'        v_row_num := 0;',
'',
'        FOR rec IN (',
'            SELECT ',
'                rp.COURSE_ID,',
'                rp.GE_REQUIREMENT_ID,',
'                rp.CUSTOM_NOTE,',
'                c.SUBJECT,',
'                c.CATALOG_NUMBER,',
'                c.TITLE,',
'                c.MIN_UNITS,',
'                c.MAX_UNITS,',
'                gr.GE_CODE,',
'                gr.NAME AS GE_NAME,',
'                (SELECT COUNT(*) FROM COURSES_COMPLETED cc WHERE cc.USER_ID = :APP_USER AND cc.COURSE_ID = rp.COURSE_ID) AS IS_DONE',
'            FROM RECOMMENDED_PATHWAY rp',
'            LEFT JOIN COURSES c ON c.COURSE_ID = rp.COURSE_ID',
'            LEFT JOIN GE_REQUIREMENTS gr ON gr.ID = rp.GE_REQUIREMENT_ID',
'            WHERE rp.PROGRAM_ID = :P1_PROGRAM_ID',
'              AND rp.SEMESTER_NUMBER = sem.SEMESTER_NUMBER',
'            ORDER BY rp.ORDER_IN_SEMESTER',
'        )',
'        LOOP',
'            v_row_num := v_row_num + 1;',
'',
'            v_html := v_html || ''<tr style="background-color:'' || CASE WHEN MOD(v_row_num, 2) = 0 THEN ''#ffffff'' ELSE ''#f9f9f9'' END || '';">'';',
'',
'            -- Checkbox',
'            v_html := v_html || ''<td style="text-align: center;"><input type="checkbox" class="course-checkbox"'';',
'            IF rec.COURSE_ID IS NOT NULL THEN',
'                v_html := v_html || '' value="'' || rec.COURSE_ID || ''"'';',
'                IF rec.IS_DONE > 0 THEN',
'                    v_html := v_html || '' checked'';',
'                END IF;',
'            END IF;',
'            v_html := v_html || ''></td>'';',
'',
'            -- Item',
'            v_html := v_html || ''<td style="padding: 12px 16px;">'';',
'            IF rec.COURSE_ID IS NOT NULL THEN',
'                v_html := v_html || ''<strong>'' || rec.SUBJECT || '' '' || rec.CATALOG_NUMBER || ''</strong>'';',
'            ELSIF rec.GE_REQUIREMENT_ID IS NOT NULL THEN',
'                v_html := v_html || ''<strong>GE '' || rec.GE_CODE || ''</strong>'';',
'            ELSE',
'                v_html := v_html || ''<strong>Note</strong>'';',
'            END IF;',
'            v_html := v_html || ''</td>'';',
'',
'            -- Description',
'            v_html := v_html || ''<td style="padding: 12px 16px;">'';',
'            IF rec.COURSE_ID IS NOT NULL THEN',
'                v_html := v_html || rec.TITLE;',
'            ELSIF rec.GE_REQUIREMENT_ID IS NOT NULL THEN',
'                v_html := v_html || rec.GE_NAME;',
'            ELSE',
'                v_html := v_html || rec.CUSTOM_NOTE;',
'            END IF;',
'            v_html := v_html || ''</td>'';',
'',
'            -- Units column',
'            v_html := v_html || ''<td style="padding: 12px 16px;">'';',
'',
'            IF rec.MIN_UNITS IS NOT NULL THEN',
'                IF rec.MIN_UNITS = rec.MAX_UNITS THEN',
'                    v_html := v_html || rec.MIN_UNITS;',
'                ELSE',
'                    v_html := v_html || rec.MIN_UNITS || ''-'' || rec.MAX_UNITS;',
'                END IF;',
'                v_total_units := v_total_units + rec.MIN_UNITS;',
'                v_total_max_units := v_total_max_units + rec.MAX_UNITS;',
'            ELSIF rec.GE_REQUIREMENT_ID IS NOT NULL OR rec.CUSTOM_NOTE IS NOT NULL THEN',
'                v_html := v_html || ''3-4'';',
'                v_total_units := v_total_units + 3;',
'                v_total_max_units := v_total_max_units + 4;',
'            ELSE',
'                v_html := v_html || ''-'';',
'            END IF;',
'',
'            v_html := v_html || ''</td></tr>'';',
'        END LOOP;',
'',
'        -- Total Units Row',
'        v_html := v_html || ''',
'            <tr style="background-color: #eef2f5; font-weight: bold;">',
'                <td colspan="3" style="text-align: right; padding: 12px 16px;">Total Units</td>',
'                <td style="padding: 12px 16px;">'' || ',
'                    CASE ',
'                        WHEN v_total_units = v_total_max_units THEN TO_CHAR(v_total_units)',
'                        ELSE TO_CHAR(v_total_units) || ''-'' || TO_CHAR(v_total_max_units)',
'                    END || ''</td>',
'            </tr>'';',
'',
'        v_html := v_html || ''</tbody></table></div>'';',
'    END LOOP;',
'',
'    RETURN v_html;',
'END;',
''))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
);
wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(9755761969520412)
,p_name=>'P5_PROGRAM_NAME'
